caption:
\header { tagline = ##f }
\layout { indent = 0\cm ragged-right = ##t
  \context { \Score \remove "Bar_number_engraver" \override SpacingSpanner.base-shortest-duration = #(ly:make-moment 6/8) }
  \context { \Staff \remove "Bar_engraver" }
}

global = { \key c \major \time 4/4 \hide Staff.TimeSignature }

violin = \relative c' { \global
  d1 e f g a bes cis, fis aes c,! b'! ees,
}

\score {
  \new Staff \with { midiInstrument = "violin" } \violin
  \layout { }
  \midi { \tempo 1=90 }
}

\relative g'' {
  \new PianoStaff <<
   \new Staff { \key a \major \time 2/2
    \set Score.tempoHideNote = ##t
     \tempo "" 2. = 64
    <cis,, e a>4.\f <cis e a>8 <cis e a>4 e a8 e cis e a4 r8 \times 2/3 { b16( cis d) } <e, b' e>2 <fis b fis'> <e b' e>4 e8 e e4 e
   }
   \new Staff { \key a \major \time 2/2 \clef bass
    <a,, e' a>4. <a e' a>8 <a e' a>4 e' a8 e cis e a4 r <gis b d>2 <a b d> <gis b d>4 r r2
   }
  >>
 }
